#include <stdio.h>

int main() {
    for (int i = 1; i <= 2; i++) {
        for (int j = 1; j <= 4; j++) {
            if (j == 3) {
                break;
            }
            printf("%d-%d ", i, j);
        }
        printf("\n");
    }
    return 0;
}
